CREATE TABLE task_doodles (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL UNIQUE, image_data TEXT NOT NULL, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_task_doodles_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE); CREATE INDEX idx_task_doodles_task_id ON task_doodles(task_id);
